import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    CircleGeometry,
    DoubleSide,
    AdditiveBlending
  } = ctx.THREE;

  const root = new Group();
  root.name = config.id || 'journal-card-1';

  const resources = [];
  const primitiveResults = [];
  const timelines = [];
  let disposed = false;

  const ink = '#16161d';
  const paper = '#e8ecf2';
  const accent = '#ff2a38';
  const surface = '#0b0b10';

  const gradientNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(
      vec3(0.086, 0.086, 0.114),
      vec3(0.14, 0.14, 0.17),
      smoothstep(0.35, 1.0, uv().y)
    ),
    smoothstep(0.0, 0.8, uv().y)
  );

  const stageMaterial = new MeshBasicNodeMaterial({
    side: DoubleSide,
    colorNode: gradientNode
  });

  const stage = new Mesh(new PlaneGeometry(7, 6), stageMaterial);
  stage.name = 'engineered-gradient-stage';
  stage.position.set(0, 0, -2.5);
  root.add(stage);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: surface,
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });

  const contactShadow = new Mesh(
    new CircleGeometry(1.65, 48),
    shadowMaterial
  );
  contactShadow.name = 'contact-shadow';
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.scale.set(1.35, 0.42, 1);
  contactShadow.position.set(0, -0.82, -0.12);
  root.add(contactShadow);

  const cardMaterial = new MeshBasicNodeMaterial({
    side: DoubleSide,
    colorNode: gradientNode
  });

  const card = new Mesh(new PlaneGeometry(2.7, 1.55), cardMaterial);
  card.name = 'journal-card-surface';
  card.position.z = 0;
  root.add(card);

  const frameMaterial = new MeshBasicNodeMaterial({
    color: ink,
    side: DoubleSide
  });

  const topFrame = new Mesh(new BoxGeometry(2.74, 0.035, 0.045), frameMaterial);
  topFrame.position.set(0, 0.79, 0.035);

  const bottomFrame = topFrame.clone();
  bottomFrame.position.y = -0.79;

  const leftFrame = new Mesh(new BoxGeometry(0.035, 1.55, 0.045), frameMaterial);
  leftFrame.position.set(-1.37, 0, 0.035);

  const rightFrame = leftFrame.clone();
  rightFrame.position.x = 1.37;

  root.add(topFrame, bottomFrame, leftFrame, rightFrame);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: accent,
    transparent: true,
    opacity: 0.95
  });

  const accentRule = new Mesh(
    new BoxGeometry(0.48, 0.045, 0.055),
    accentMaterial
  );
  accentRule.name = 'signal-red-rule';
  accentRule.position.set(-1.03, -0.47, 0.08);
  root.add(accentRule);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let textOffset = 0.17;

  for (const item of items) {
    const content = typeof item === 'string' ? item : item?.text;
    if (typeof content !== 'string' || content.length === 0) continue;

    const typography = typeof item === 'object' ? item.typography : undefined;
    const textObject = ctx.fontAtlas.createText(content, {
      fontSize: typography?.fontSize ?? 39,
      color: paper,
      align: 'left',
      letterSpacingPx: item?.role === 'label' ? 3 : 0
    });

    textObject.name = item?.role || 'headline';
    textObject.position.set(-1.04, textOffset, 0.1);
    root.add(textObject);
    textOffset -= item?.role === 'caption' ? 0.22 : 0.3;
  }

  const loadTexture = config.imageUrl || config.intent?.visualSpec?.imageUrl;
  if (loadTexture) {
    ctx.textureLoader.loadTexture(loadTexture).then((loadedTexture) => {
      if (disposed) {
        loadedTexture.dispose?.();
        return;
      }

      resources.push(loadedTexture);
      if (ctx.THREE.SRGBColorSpace) {
        loadedTexture.colorSpace = ctx.THREE.SRGBColorSpace;
      }

      const imageNode = texture(loadedTexture, uv());
      cardMaterial.colorNode = mix(gradientNode, imageNode, 0.34);
      cardMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  root.position.y = -0.2;
  const entrance = gsap.timeline({ paused: false });
  entrance.to(root.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out'
  });
  timelines.push(entrance);

  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      if (!primitive?.name || typeof ctx.primitives?.[primitive.name] !== 'function') {
        continue;
      }

      const result = ctx.primitives[primitive.name](
        root,
        primitive.params || {}
      );

      if (result) primitiveResults.push(result);
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline.kill?.();
    }

    for (const result of primitiveResults) {
      result?.timeline?.kill?.();
      result?.cleanup?.();
    }

    root.traverse((object) => {
      if (object.geometry) object.geometry.dispose?.();

      const material = object.material;
      if (Array.isArray(material)) {
        for (const entry of material) entry?.dispose?.();
      } else {
        material?.dispose?.();
      }
    });

    for (const resource of resources) {
      resource.dispose?.();
    }
  };

  return root;
}
